package com.mockarena.assessment.infrastructure.question;
import com.fasterxml.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.util.*;
@Component public class RestQuestionCandidateContentClient implements QuestionCandidateContentClient { private final RestClient client; public RestQuestionCandidateContentClient(@Value("${question-service.base-url}")String base){client=RestClient.builder().baseUrl(base).build();} public List<QuestionCandidateContent> resolve(List<UUID> ids){try{Response r=client.post().uri("/internal/v3/question-versions/candidate-content").body(new Request(ids)).retrieve().body(Response.class);if(r==null||r.entries()==null||r.entries().size()!=ids.size())throw new QuestionServiceUnavailableException(new IllegalStateException());return r.entries().stream().map(e->new QuestionCandidateContent(e.questionId(),e.questionVersionId(),e.questionTypeCode(),e.title(),e.stem(),e.options()==null?List.of():e.options().stream().map(o->new QuestionCandidateContent.Option(o.id(),o.text())).toList(),e.constraints(),e.examples(),e.programmingLanguages())).toList();}catch(RestClientException e){throw new QuestionServiceUnavailableException(e);}} record Request(List<UUID> questionVersionIds){} record Response(List<Entry> entries){} record Entry(UUID questionId,UUID questionVersionId,String questionTypeCode,String title,String stem,List<Option> options,String constraints,JsonNode examples,JsonNode programmingLanguages){} record Option(String id,String text){} }
